import {c,type FinanceLesson,type FinanceExercise} from '../../lib/finance-types';
const ex=(id:string,kind:FinanceExercise['kind'],vi:string,en:string,hvi:string,hen:string,avi:string,aen:string,expected?:number):FinanceExercise=>({id,kind,question:c(vi,en),hint:c(hvi,hen),answer:c(avi,aen),...(expected===undefined?{}:{numeric:{expected,tolerance:0.000001}})});
const sec=(vi:string,en:string,bvi:string,ben:string)=>({title:c(vi,en),body:c(bvi,ben)});
const base={title:'OpenStax — Principles of Finance',url:'https://openstax.org/books/principles-finance/pages/1-1-what-is-finance',section:'1.1 What Is Finance? Nguồn khái niệm; các ví dụ và bài tập tự biên soạn.'};
const income={title:'OpenStax — Principles of Finance',url:'https://openstax.org/books/principles-finance/pages/15-1-risk-and-return-to-an-individual-asset',section:'15.1 Individual Investment Realized Return; price changes, income and return.'};
const returns={title:'Eric Zivot — Return Calculations',url:'https://faculty.washington.edu/ezivot/econ424/returnCalculations.pdf',section:'1.2 Asset Return Calculations; 1.2.1 Simple Returns. Ví dụ có phí tự biên soạn.'};

export const foundations:FinanceLesson[]=[
{id:'market',moduleId:'finance',title:c('Thị trường tài chính','Financial markets'),summary:c('Hiểu tài sản, hợp đồng, giá chào và giao dịch đã khớp.','Understand assets, contracts, quotes and executed trades.'),why:c('Trước khi dự đoán giá, cần biết mình mua bán quyền gì và dữ liệu mô tả điều gì.','Before predicting prices, establish what rights are traded and what the data describe.'),application:c('Thiết kế danh mục sản phẩm để không nhầm cổ phiếu, BTC giao ngay và hợp đồng theo BTC.','Build an instrument catalog distinguishing shares, spot BTC and BTC-linked contracts.'),prerequisites:[],project:'ledger',sections:[
sec('Tài sản và hợp đồng','Assets and contracts','Tài chính nghiên cứu cách huy động, sử dụng và chuyển tiền qua thời gian trong điều kiện có rủi ro. Cổ phiếu biểu thị một phần quyền sở hữu doanh nghiệp; trái phiếu là hợp đồng nợ có điều kiện trả tiền. Một token không mặc nhiên cho quyền sở hữu công ty hay nhận cổ tức: cần đọc cơ chế của tài sản cụ thể. Forex là trao đổi hai đồng tiền.\n\nMã giao dịch chỉ là nhãn của nhà cung cấp, chưa mô tả đầy đủ hợp đồng. Cần lưu sàn, loại sản phẩm, tài sản cơ sở, đơn vị khối lượng và đồng tiền báo giá. Hai sản phẩm biến động gần nhau vẫn có thể khác về quyền sở hữu, dòng tiền và nghĩa vụ.','Finance concerns raising, using and transferring money over time under risk. A share represents company ownership; a bond is a debt contract with payment terms. A token does not automatically confer company ownership or dividends; inspect its actual mechanism. FX exchanges one currency for another.\n\nA ticker is a provider label, not a full contract description. Record venue, product type, underlying asset, quantity unit and quote currency. Products that move together can still differ in ownership, cash flows and obligations.'),
sec('Giá chào và khớp lệnh','Quotes and execution','Bid là giá người khác đang chào mua; ask là giá người khác đang chào bán. Người mua ngay thường cần gặp chào bán. Chênh lệch ask trừ bid gọi là spread. Chào giá còn có khối lượng: giá tốt nhất có thể chỉ đủ cho một phần lệnh.\n\nLệnh là yêu cầu giao dịch. Khớp lệnh là phần yêu cầu đã thực hiện. Lệnh giới hạn đặt giá tối đa khi mua hoặc tối thiểu khi bán, nhưng không bảo đảm khớp. Một hàng dữ liệu có giá không chứng minh hệ thống đã giao dịch được ở giá ấy.','Bid is another participant’s offered purchase price; ask is an offered sale price. An immediate buyer generally meets an ask. Ask minus bid is the spread. Quotes have quantities, so the best price may cover only part of an order.\n\nAn order is a request; an execution is its completed portion. A limit order sets a maximum purchase or minimum sale price but may not fill. A recorded price does not establish that the system traded there.'),
sec('Một giao dịch trong hệ thống','A trade through the system','Nếu bid là 99 và ask là 101 USD, mua một cổ phiếu ở 101 rồi bán ngay ở 99 gây lỗ 2 USD trước phí dù chào giá chưa thay đổi. Dùng giá trung bình 100 cho cả hai chiều sẽ che mất chi phí.\n\nHệ thống phải nhận dữ liệu, quyết định, kiểm tra tiền, gửi lệnh rồi chờ xác nhận. Lưu thời điểm quan sát, quyết định và khớp riêng: chúng không nhất thiết trùng nhau. Trong ví dụ có thể đơn giản hóa, nhưng khi đánh giá hệ thống phải kiểm tra giả định giá và thời gian.','With a bid of 99 and ask of 101 USD, buying one share at 101 and immediately selling at 99 loses 2 USD before fees without any quote change. Using midpoint 100 for both sides hides the cost.\n\nA system receives data, decides, checks cash, submits and waits for confirmation. Store observation, decision and execution times separately. Simplifications may help examples, but evaluation must examine pricing and timing assumptions.')],exercises:[
ex('market-1','concept','Vì sao ticker BTC chưa đủ để xác định sản phẩm?','Why is ticker BTC insufficient to identify a product?','Xét giao ngay và hợp đồng.','Consider spot versus a contract.','Cần biết sàn, loại hợp đồng, đơn vị và đồng tiền thanh toán. BTC giao ngay và hợp đồng theo BTC không có cùng quyền sở hữu và dòng tiền.','Venue, contract type, units and settlement currency matter. Spot BTC and BTC-linked contracts do not share identical ownership rights or cash flows.'),
ex('market-2','calculation','Mua một đơn vị ở ask 51, bán ở bid 49. Nhập độ lớn khoản lỗ trước phí.','Buy one unit at ask 51 and sell at bid 49. Enter the loss magnitude before fees.','So tiền trả với tiền nhận.','Compare payment and receipt.','Trả 51, nhận 49, nên mất 2. Spread có thể gây chi phí ngay cả khi giá chào không đổi.','Pay 51 and receive 49: lose two. Spread costs can occur without a quote change.',2),
ex('market-3','implementation','Làm sao tránh cập nhật vị thế ngay khi gửi lệnh?','How can position updates avoid treating submission as execution?','Phân biệt yêu cầu và xác nhận khớp.','Separate requests from confirmed fills.','Lưu trạng thái submitted, accepted, partially-filled, filled hoặc rejected. Chỉ cập nhật vị thế bằng lượng khớp được xác nhận; dùng mã giao dịch để tránh ghi hai lần.','Track submitted, accepted, partially-filled, filled or rejected states. Update positions only from confirmed filled quantity, using execution IDs to prevent duplicates.')],sources:[base,{title:'CME — Introduction to Futures',url:'https://www.cmegroup.com/education/courses/introduction-to-futures.html',section:'Contract specifications, notional value, expiration and settlement.'}]},

{id:'cash-flow',moduleId:'finance',title:c('Dòng tiền','Cash flows'),summary:c('Lập sổ tiền vào, tiền ra và tách vốn nộp thêm khỏi thu nhập.','Record receipts and payments, separating added capital from income.'),why:c('Thiếu một khoản phí hoặc sai dấu có thể làm sai cả báo cáo.','An omitted fee or incorrect sign can invalidate the report.'),application:c('Dùng cùng cấu trúc sổ cho mua cổ phiếu, mua crypto và đổi ngoại tệ.','Use one ledger structure for equity purchases, crypto and currency exchanges.'),prerequisites:['market'],project:'ledger',sections:[
sec('Góc nhìn và phạm vi','Perspective and scope','Dòng tiền là khoản tiền thực đi vào hoặc đi ra ở một thời điểm. Theo góc nhìn nhà đầu tư, nhận tiền ghi dương và trả tiền ghi âm. Mua tài sản là tiền ra nhưng đồng thời nhận tài sản, nên không thể gọi toàn bộ khoản mua là lỗ.\n\nChọn phạm vi trước khi cộng: một vị thế hay cả tài khoản. Nộp tiền từ ngân hàng vào tài khoản môi giới làm tăng tiền tài khoản nhưng không tạo lợi nhuận chiến lược. Dòng vốn từ chủ tài khoản cần được tách khỏi thu nhập do tài sản tạo ra.','A cash flow is an actual receipt or payment at a time. From the investor’s perspective, receipts are positive and payments negative. Buying sends cash out but brings an asset in; the entire purchase is not a loss.\n\nDefine scope before summing: one position or a whole account. Depositing bank funds into a brokerage account increases its cash but creates no strategy profit. Separate owner capital from asset-generated income.'),
sec('Tiền và tài sản','Cash and assets','Mua 4 cổ phiếu giá 50 USD, phí cả lệnh 1 USD: ghi tiền mua −200 và phí −1 USD; tiền giảm 201, số cổ phiếu tăng 4. Khi bán, số lượng giảm và tiền tăng theo phần đã khớp.\n\nPhí nên có dòng riêng hoặc trường riêng với quy ước rõ. Nếu dữ liệu đã ghi tiền bán sau phí mà bạn trừ phí lần nữa, kết quả sẽ sai. Với nhiều đồng tiền, ghi riêng từng loại trước khi quy đổi. Không cộng 100 USD với 100 EUR rồi gọi tổng là 200 USD.','Buy four shares at 50 USD with a total fee of one: record purchase −200 and fee −1 USD. Cash falls 201 while shares increase four. Sales reduce quantity and increase cash according to executions.\n\nFees need explicit entries or fields. Subtracting them from already-net proceeds double-counts costs. Reconcile currencies separately before conversion; 100 USD plus 100 EUR is not 200 USD.'),
sec('Đối chiếu số dư','Balance reconciliation','Đối chiếu là kiểm tra tiền đầu cộng mọi dòng tiền có bằng tiền cuối hay không. Nếu đầu có 300 USD, mua mất 201 và nhận cổ tức 8 thì cuối còn 107 USD tiền mặt, đồng thời vẫn giữ bốn cổ phiếu. Số 107 không phải toàn bộ giá trị tài khoản.\n\nMỗi dòng cần có thời gian, đồng tiền, loại sự kiện, số tiền có dấu và mã giao dịch. Nếu tổng không khớp, tìm khoản thiếu, lặp, nhầm tiền tệ hoặc sai thời gian; không thêm một khoản “điều chỉnh” không giải thích chỉ để ép hai bên bằng nhau.','Reconciliation checks whether opening cash plus all flows equals closing cash. Starting at 300 USD, paying 201 and receiving eight in dividends leaves 107 USD cash and four shares. The 107 is not total account value.\n\nEach entry needs time, currency, event type, signed amount and transaction ID. If balances disagree, investigate missing or duplicated entries, currency errors and timing. Do not invent an unexplained adjustment merely to force agreement.')],exercises:[
ex('cash-1','concept','Tiền mặt giảm sau khi mua có chứng minh tài khoản mất toàn bộ số tiền ấy không?','Does a cash decline after purchase establish an equal loss of total wealth?','Nhìn cả tài sản vừa nhận.','Include the acquired asset.','Không. Tiền được đổi lấy tài sản. Muốn đo tổng giá trị, cần cộng tiền với giá trị tài sản theo quy tắc định giá và trừ nghĩa vụ nếu có.','No. Cash was exchanged for an asset. Total value requires cash plus asset valuation under a stated rule, less any liabilities.'),
ex('cash-2','calculation','Tiền đầu 500; nộp 100; mua tài sản trả 200; phí 2; cổ tức nhận 5. Tiền cuối bao nhiêu?','Opening cash 500; deposit 100; purchase payment 200; fee two; dividend five. What is closing cash?','Cộng tiền nhận, trừ tiền trả.','Add receipts, subtract payments.','Tiền cuối 403. Khoản nộp 100 là vốn ngoài, không phải lãi; tài sản mua vẫn theo dõi riêng.','Closing cash is 403. The deposit of 100 is external capital, not profit; purchased assets remain separately tracked.',403),
ex('cash-3','implementation','Đề xuất các cột cho một sổ tiền kiểm tra được.','Propose columns for an auditable cash ledger.','Cần truy được tiền từ sự kiện nào.','Make each amount traceable to an event.','event_id, timestamp, currency, signed_amount, event_type, trade_id, source. Mã ổn định giúp phát hiện nhập lặp; giữ bản gốc để kiểm tra bước chuẩn hóa.','Use event_id, timestamp, currency, signed_amount, event_type, trade_id and source. Stable IDs detect duplicate imports; preserve raw records to audit normalization.')],sources:[base,income]},

{id:'pnl',moduleId:'finance',title:c('P&L','P&L'),summary:c('Tính kết quả sau thu nhập và phí từ sổ tiền của một vị thế.','Compute a position’s result after income and fees from its ledger.'),why:c('Tiền bán không phải toàn bộ lợi nhuận, và giá tăng chưa chắc có lời.','Sale proceeds are not all profit, and price increases do not guarantee gains.'),application:c('Dùng một phép tính P&L nhất quán trong sổ giao dịch và backtest.','Use consistent P&L calculations in trade ledgers and backtests.'),prerequisites:['cash-flow'],project:'ledger',sections:[
sec('Định nghĩa các khoản','Define the amounts','P&L là viết tắt của profit and loss, nghĩa là lãi/lỗ. Gọi $q>0$ là số lượng không đổi, $P_0$ là giá mua, $P_1$ là giá bán mỗi đơn vị, $D$ là cổ tức mỗi đơn vị, $F_0$ và $F_1$ là phí cả lệnh mua và bán. Phí nhập dưới dạng số không âm.\n\nXét mua bằng tiền của mình rồi bán hết, không thuế, không đổi tiền tệ. Cổ tức giữ bằng tiền không sinh lãi. Vốn đầu $C_0=qP_0+F_0$; tiền cuối $C_1=qP_1+qD-F_1$. Chỉ khi xác định đủ những khoản này mới tính kết quả.','P&L means profit and loss. Let $q>0$ be constant quantity, $P_0$ purchase price, $P_1$ sale price per unit, $D$ dividends per unit, and $F_0$ and $F_1$ total purchase and sale fees. Enter fees as nonnegative amounts.\n\nBuy with your own cash and sell everything, without tax or currency changes. Hold dividends as non-interest-bearing cash. Initial outlay is $C_0=qP_0+F_0$ and ending cash $C_1=qP_1+qD-F_1$. Define these before computing the result.'),
sec('Cách tính P&L','Calculating P&L','Gọi $L$ là lãi/lỗ. Lấy tiền cuối trừ vốn đầu và khai triển ngoặc: $L=C_1-C_0=q(P_1-P_0+D)-F_0-F_1$. Ba hạng trong ngoặc là tiền mỗi đơn vị tài sản; nhân với $q$ đưa về tiền cả vị thế. Phí cả lệnh nằm ngoài ngoặc để không bị nhân thừa.\n\nMua 10 cổ phiếu ở 100, bán 108, cổ tức 2 mỗi cổ phiếu, phí mỗi bên 1 USD: vốn đầu 1001, tiền cuối 1099, lãi 98 USD. Kiểm tra bằng thành phần: tăng giá đem 80, cổ tức đem 20, phí lấy đi 2, còn 98.','Let $L$ denote P&L. Subtract initial from ending cash and expand: $L=C_1-C_0=q(P_1-P_0+D)-F_0-F_1$. Terms inside the bracket are money per unit; multiplying by $q$ produces position-level money. Whole-order fees remain outside to avoid multiplying them again.\n\nBuy ten shares at 100, sell at 108, receive two per share in dividends and pay one USD each way: initial outlay 1001, ending cash 1099, profit 98. Independently, price gain 80 plus dividends 20 less fees two gives 98.'),
sec('P&L đã thực hiện và chưa thực hiện','Realized and unrealized P&L','Nếu chưa bán, dùng một giá quan sát chỉ tạo ước tính lãi/lỗ chưa thực hiện. Cần ghi rõ dùng bid, ask hay giá giao dịch cuối; phí bán cũng có thể chỉ là dự kiến. Sau khi bán, dùng giá và lượng khớp thực để ghi nhận.\n\nMua 10 ở 100, bán 100.10, không cổ tức, tổng phí 2 USD: tăng giá đem 1 USD nhưng phí lấy đi 2, nên lỗ 1. Nếu dùng giá đã điều chỉnh cổ tức, không tự cộng cổ tức lần nữa; phải đọc định nghĩa dữ liệu.','Before selling, an observed price yields an unrealized estimate. State whether it uses bid, ask or last trade; exit fees may also be estimates. After sale, use actual execution prices and quantities.\n\nBuying ten at 100 and selling at 100.10 with no dividend and total fees of two generates one USD of price gains but loses one net. With dividend-adjusted prices, do not automatically add dividends again; inspect the data definition.')],exercises:[
ex("pnl-1","concept","Vì sao phải phân biệt cổ tức mỗi cổ phiếu với phí của cả lệnh?","Why distinguish a per-share dividend from a whole-order fee?","Xem khoản nào thay đổi theo số lượng tài sản.","Identify which amount scales with quantity.","Cổ tức mỗi cổ phiếu phải nhân số cổ phiếu để ra tiền cả vị thế. Phí đã là tiền của cả lệnh nên chỉ tính một lần. Nhầm hai quy mô sẽ làm sai dòng tiền.","Multiply a per-share dividend by share quantity to obtain position-level cash. A whole-order fee is already a total and is counted once. Mixing these scales misstates cash flows."),
ex('pnl-2','calculation','Mua 5 cổ phiếu giá 80, bán 76, cổ tức 1.50 mỗi cổ phiếu, phí mua 2 và bán 3 USD. P&L bao nhiêu USD?','Buy five at 80, sell at 76, receive 1.50 per share and pay fees of two and three USD. What is P&L?','Tách giá, cổ tức, phí.','Separate price, dividends and fees.','Giá giảm gây lỗ 20, cổ tức thêm 7.50, phí mất 5: kết quả −17.50 USD. Vốn đầu 402 và tiền cuối 384.50 cho cùng kết quả.','Price loss 20 plus dividends 7.50 less fees five yields −17.50 USD. Initial outlay 402 and ending cash 384.50 confirm it.',-17.5),
ex('pnl-3','concept','Ảnh chụp màn hình giá có đủ chứng minh lãi đã thực hiện không?','Does a price screenshot establish realized profit?','Phân biệt quan sát giá và xác nhận bán.','Distinguish observations from confirmed sales.','Không. Cần bản ghi khớp bán với lượng, giá và phí thực. Nếu chưa bán, chỉ báo cáo định giá chưa thực hiện với giả định rõ.','No. Actual sale records with quantities, prices and fees are required. Otherwise report an unrealized valuation with explicit assumptions.')],sources:[income,returns]},

{id:'returns',moduleId:'finance',title:c('Tỷ suất sinh lời','Returns'),summary:c('Đo lãi/lỗ theo vốn đầu và ghép lợi suất qua nhiều kỳ.','Scale P&L by initial capital and combine returns across periods.'),why:c('Cần mốc vốn và thời gian rõ để so các khoản đầu tư khác nhau.','Comparisons require explicit capital and time bases.'),application:c('Báo cáo hiệu quả sau phí thay vì chỉ tiền lãi tuyệt đối.','Report net performance rather than absolute profit alone.'),prerequisites:['pnl'],project:'ledger',sections:[
sec('Mẫu số của lợi suất','The return denominator','Với vốn đầu $C_0>0$ và tiền cuối $C_1$, lợi suất đơn $R=(C_1-C_0)/C_0=C_1/C_0-1$. Tử số đo phần tăng/giảm, mẫu số là vốn làm mốc. Cả hai là tiền nên tỷ lệ không mang đơn vị tiền.\n\nVốn 1001 và tiền cuối 1099 cho $R=98/1001$, khoảng 9.79%. Số thập phân 0.10 tương ứng 10%, không phải 0.10%. Tỷ số tiền cuối trên vốn đầu còn chứa vốn gốc nên phải trừ 1.','For initial cash $C_0>0$ and ending cash $C_1$, simple return is $R=(C_1-C_0)/C_0=C_1/C_0-1$. The numerator measures change and the denominator reference capital. Both are monetary amounts, leaving a unitless ratio.\n\nInitial 1001 and ending 1099 give $R=98/1001$, about 9.79%. Decimal 0.10 means 10%, not 0.10%. The ending-to-initial ratio includes original capital, hence subtracting one.'),
sec('Lợi suất nhiều kỳ','Multi-period returns','Nếu không thêm/rút vốn và tiền lãi giữ lại, kỳ đầu nhân vốn với $1+R_1$, kỳ sau nhân tiếp $1+R_2$. $R_1$ và $R_2$ là hai lợi suất liên tiếp. Lợi suất chung là $(1+R_1)(1+R_2)-1$.\n\nTăng 20% rồi giảm 20% biến 100 thành 120 rồi còn 96, tức mất 4%. Không cộng hai tỷ lệ để kết luận hòa vốn vì chúng áp lên hai mốc vốn khác nhau.','With no contributions or withdrawals and gains retained, capital is multiplied first by $1+R_1$ and then by $1+R_2$. Here $R_1$ and $R_2$ are consecutive returns. Combined return is $(1+R_1)(1+R_2)-1$.\n\nGaining 20% then losing 20% takes 100 to 120 and then 96, a 4% loss. Adding rates falsely implies break-even because their capital bases differ.'),
sec('Đọc báo cáo','Read a report','Một lợi suất cần đi kèm kỳ đo, đồng tiền, quy tắc mẫu số, phí và thu nhập được tính. Lợi suất một tuần chưa thể so trực tiếp với một năm. Nộp thêm vốn giữa kỳ cần phương pháp riêng; không coi tiền nộp là lợi nhuận.\n\nKhi so chiến lược với phương án đối chiếu, giữ cách tính nhất quán. Ghi rõ thực tế hay backtest, trước hay sau phí. Một con số phần trăm không nói đủ về rủi ro hoặc khả năng thực hiện giao dịch.','Report period, currency, denominator, costs and included income with each return. A weekly return is not directly comparable with an annual one. Mid-period capital flows need a suitable method rather than being treated as profit.\n\nUse consistent conventions for strategy and benchmark. Label actual versus backtested and gross versus net results. A percentage alone cannot describe risk or execution feasibility.')],exercises:[
ex("returns-1","concept","Vì sao lấy tiền cuối chia vốn đầu vẫn chưa phải lợi suất đơn?","Why is ending cash divided by initial capital not yet a simple return?","Tỷ số đó có chứa phần vốn ban đầu không?","Does that ratio still include original capital?","Tỷ số còn chứa vốn gốc. Khi tiền cuối bằng vốn đầu, tỷ số bằng 1 nhưng lợi suất phải bằng 0; vì thế cần trừ 1.","The ratio includes original capital. When ending and initial cash are equal, the ratio is one but return is zero, so subtract one."),
ex('returns-2','calculation','Tăng 10% rồi giảm 10%, không thêm/rút vốn. Nhập lợi suất chung thập phân.','Gain 10% then lose 10% without flows. Enter combined decimal return.','Theo dõi vốn đầu 100.','Track initial capital of 100.','100 thành 110 rồi còn 99, nên lợi suất −0.01. Hai tỷ lệ không dùng cùng mẫu số.','100 becomes 110 then 99, giving −0.01. The two rates use different bases.',-0.01),
ex('returns-3','concept','Vì sao chỉ ghi “lãi 12%” chưa đủ để so chiến lược?','Why is “12% return” insufficient to compare strategies?','Cần biết phép đo đã tính gì.','Establish what was measured.','Cần thời gian, vốn nền, đồng tiền, chi phí, thu nhập và dòng vốn ngoài. Cần biết dữ liệu, cách khớp và rủi ro; con số riêng lẻ chưa đủ xếp hạng.','Clarify period, capital, currency, costs, income and external flows, plus data, execution and risk. The number alone cannot rank strategies.')],sources:[returns,income]},
{id:'interest',moduleId:'finance',title:c('Lãi suất và giá trị thời gian','Interest and time value'),summary:c('Tính lãi kép và quy tiền tương lai về hiện tại.','Calculate compounding and discount future cash.'),why:c('Dòng tiền ở hai thời điểm khác nhau cần một cơ sở so sánh.','Cash at different times requires a comparison basis.'),application:c('Tính lãi tiền mặt và kiểm tra đơn vị thời gian của chi phí giữ vị thế.','Calculate cash accrual and check holding-cost time units.'),prerequisites:['returns'],project:'ledger',sections:[
sec('Lãi một kỳ','One-period interest','Gọi $V_0$ là vốn đầu và $r$ là lãi suất mỗi kỳ dạng thập phân. Tiền lãi là $V_0r$, nên tiền cuối $V_1=V_0(1+r)$. Kỳ có thể là tháng hoặc năm nhưng phải thống nhất với $r$. Dùng lãi suất tháng cho một bước rồi gọi đó là một năm sẽ sai.\n\nTa đang giả định mức lãi đã cho áp dụng trọn kỳ, không phí và không mất khả năng thanh toán. Đây là điều kiện mô hình, không phải lời hứa rằng mọi khoản đầu tư trả lãi chắc chắn.','Let $V_0$ be starting capital and $r$ the decimal rate per period. Interest is $V_0r$, so ending cash is $V_1=V_0(1+r)$. Periods may be months or years but must match $r$. Applying a monthly rate once does not produce an annual result.\n\nThis assumes the rate applies throughout the period without fees or payment failure. These are model conditions, not a promise of certain investment income.'),
sec('Lãi kép','Compounding','Khi lãi giữ lại, kỳ sau tính lãi trên cả vốn và lãi trước đó. Lặp phép nhân $1+r$ qua $n$ kỳ cho $V_n=V_0(1+r)^n$, với $n$ là số kỳ và lãi suất không đổi. 1000 USD ở 10% mỗi năm thành 1100 rồi 1210 sau hai năm.\n\nLãi đơn là quy ước khác: mỗi kỳ chỉ tính lãi trên vốn gốc, nên ví dụ ấy cho 1200. Khoản 10 chênh lệch là lãi sinh ra từ lãi năm đầu. Nếu mức lãi đổi giữa các kỳ, nhân từng hệ số tương ứng, không tùy ý lấy một mức làm đại diện.','Retained interest earns interest in later periods. Repeating $1+r$ for $n$ periods gives $V_n=V_0(1+r)^n$, where $n$ counts periods and the rate is constant. At 10% annually, 1000 USD becomes 1100 then 1210 in two years.\n\nSimple interest instead applies each period’s rate only to original principal, producing 1200. The ten difference is interest on first-year interest. Changing rates require their separate growth factors, not an arbitrary representative rate.'),
sec('Chiết khấu','Discounting','Giá trị hiện tại là số tiền hôm nay tương đương khoản tương lai theo mức lãi suất chọn. Đảo công thức tăng trưởng cho $V_0=V_n/(1+r)^n$. Đây là chiết khấu. Với mức so sánh 10% mỗi năm, 1210 USD sau hai năm tương đương 1000 hôm nay theo mô hình.\n\nGiá trị phụ thuộc thời hạn, rủi ro và mức lãi suất dùng. Hệ thống cần lưu quy tắc ghép lãi, số ngày tính và đơn vị tỷ lệ. Một trường “rate” không có định nghĩa chưa đủ để tính chi phí vay.','Present value is today’s cash equivalent of future cash under a selected rate. Inverting growth gives $V_0=V_n/(1+r)^n$: discounting. At a 10% annual comparison rate, 1210 USD in two years corresponds to 1000 today in this model.\n\nValue depends on timing, risk and the chosen rate. Store compounding, day-count and rate-unit conventions. An undefined “rate” field is insufficient for borrowing-cost calculations.')],exercises:[
ex("interest-1","concept","Lãi suất 1% mỗi tháng có thể áp một lần để tính tiền cuối một năm không?","Can a monthly rate of 1% be applied once to compute cash after a year?","Đơn vị của kỳ tính phải khớp đơn vị lãi suất.","The calculation period must match the rate period.","Không. Một lần áp mức lãi tháng chỉ mô tả một tháng. Muốn tính cả năm còn cần biết cách tính lãi qua các tháng và lãi có được giữ lại hay không.","No. Applying a monthly rate once describes one month. A full-year calculation also requires the interest convention across months and whether interest is retained."),
ex('interest-2','calculation','1000 với lãi kép 10% mỗi năm qua hai năm, không phí. Tiền cuối bao nhiêu?','1000 at 10% annual compounding for two years without fees. What is ending cash?','Tính từng năm.','Compute year by year.','Năm đầu 1100; năm sau tiền lãi 110, tổng 1210.','Year one ends at 1100; year two earns 110, reaching 1210.',1210),
ex('interest-3','implementation','API báo rate = 0.05. Cần biết gì để tính phí vay một ngày?','An API reports rate = 0.05. What is needed for one-day borrowing cost?','Đơn vị thời gian và quy ước.','Time units and conventions.','Cần biết dạng thập phân hay phần trăm, kỳ của lãi suất, đơn hay kép, số ngày quy ước, số dư chịu lãi và phí bổ sung. Không suy ra từ tên trường.','Determine decimal versus percentage, rate period, simple versus compound treatment, day count, applicable balance and extra fees. The name alone does not establish these.')],sources:[{title:'OpenStax — Principles of Finance',url:'https://openstax.org/books/principles-finance/pages/7-2-time-value-of-money-tvm-basics',section:'7.2 Single-Period Scenario and compounding.'},{...returns,section:'1.1 The Time Value of Money; future and present value.'}]},

{id:'risk',moduleId:'finance',title:c('Rủi ro','Risk'),summary:c('Đọc lợi nhuận cùng bất định và mức sụt giảm vốn.','Interpret profit alongside uncertainty and drawdown.'),why:c('Cùng tiền cuối kỳ có thể đi kèm trải nghiệm tổn thất rất khác.','Equal ending capital can conceal different loss experiences.'),application:c('Thêm đường vốn và drawdown vào báo cáo chiến lược.','Add equity paths and drawdowns to strategy reports.'),prerequisites:['returns'],project:'ledger',sections:[
sec('Kết quả và bất định','Outcomes and uncertainty','Lợi suất đã xảy ra mô tả kết quả; rủi ro liên quan tới những kết quả chưa chắc chắn và hậu quả của chúng. Có thể mất tiền do giá thay đổi, không bán được như mong muốn, đối tác không trả hoặc hệ thống gửi sai lệnh. Một chỉ số biến động giá không bao phủ mọi nguồn tổn thất.\n\nHãy hỏi mất bao nhiêu, trong tình huống nào, trong bao lâu và còn đủ tiền để tiếp tục không. Lợi nhuận cao không tự trả lời các câu hỏi ấy.','Realized return describes an outcome; risk concerns uncertain outcomes and their consequences. Loss may come from price changes, inability to exit, counterparty failure or erroneous orders. Price volatility alone does not cover every source.\n\nAsk how much can be lost, under what conditions, for how long and whether sufficient capital remains. High profit does not answer those questions.'),
sec('Sụt giảm từ đỉnh','Drawdown from a peak','Gọi $V_t$ là giá trị tài khoản tại thời điểm $t$, $H_t$ là giá trị cao nhất đã đạt tới thời điểm ấy. Với $H_t>0$, drawdown dạng dương là $d_t=(H_t-V_t)/H_t$. Không dùng một đỉnh trong tương lai để tính quá khứ. Maximum drawdown là mức $d_t$ lớn nhất trong đoạn quan sát.\n\nĐường vốn 100, 120, 90, 110 có đỉnh chạy 100, 120, 120, 120. Drawdown sâu nhất 25% ở mức vốn 90, dù cuối đoạn vẫn lời 10% so đầu. Ví dụ giả định không nộp/rút tiền.','Let $V_t$ be account value at time $t$ and $H_t$ its highest value reached by then. For $H_t>0$, positive drawdown is $d_t=(H_t-V_t)/H_t$. Do not use a future peak to evaluate the past. Maximum drawdown is the greatest $d_t$ over the observed interval.\n\nValues 100, 120, 90, 110 have running peaks 100, 120, 120, 120. Deepest drawdown is 25% at value 90 despite an ending gain of 10%. This assumes no deposits or withdrawals.'),
sec('Hồi vốn','Recovering capital','Mất tỷ lệ $d$ để lại $1-d$ lần vốn cũ. Tỷ lệ tăng cần thiết $g$ thỏa $(1-d)(1+g)=1$, nên $g=d/(1-d)$ khi $0\\le d<1$. Mất 20% cần tăng 25% để hồi vốn vì nền vốn đã nhỏ hơn.\n\nDrawdown lịch sử không phải giới hạn lỗ tương lai. Cần thử các tình huống như phí tăng, mất dữ liệu hoặc không thoát vị thế. Ghi rõ chúng là tình huống giả định và nêu cách tạo ra, không lẫn với quan sát thật.','Losing fraction $d$ leaves $1-d$ times original capital. Recovery gain $g$ satisfies $(1-d)(1+g)=1$, giving $g=d/(1-d)$ when $0\\le d<1$. A 20% loss requires a 25% gain because recovery starts from less capital.\n\nHistorical drawdown is not a future loss bound. Test scenarios such as increased costs, missing data or inability to exit. Label their assumptions and construction rather than presenting them as observations.')],exercises:[
ex("risk-1","concept","Giá ít biến động có loại bỏ rủi ro hệ thống gửi sai lệnh không?","Does low price volatility eliminate the risk of erroneous orders?","Hai nguồn tổn thất có cùng nguyên nhân không?","Do these loss sources share the same cause?","Không. Biến động giá mô tả một nguồn bất định; lỗi gửi lệnh thuộc vận hành và có thể gây mất tiền ngay cả khi giá ổn định. Cần đánh giá riêng cách hệ thống phát hiện và xử lý lỗi.","No. Price volatility captures one uncertainty source; erroneous orders are an operational risk and can lose money even at stable prices. Assess detection and error handling separately."),
ex('risk-2','calculation','Đỉnh vốn đã đạt 200, hiện còn 160, không nộp/rút. Nhập drawdown thập phân dương.','Past peak 200, current value 160, no flows. Enter positive decimal drawdown.','Chia phần giảm cho đỉnh.','Divide the decline by the peak.','Giảm 40 trên 200 nên drawdown 0.20. Không nhất thiết là lợi suất từ ngày đầu nếu vốn đầu khác 200.','A decline of 40 from 200 gives 0.20. This need not be the inception return if initial capital differs.',0.2),
ex('risk-3','concept','Backtest có maximum drawdown 10%. Có được gọi 10% là lỗ tối đa chắc chắn không?','A backtest has 10% maximum drawdown. Is that a guaranteed maximum loss?','Phân biệt mẫu quan sát và mọi tương lai.','Distinguish an observed sample from every future.','Không. Chỉ báo cáo 10% trong đoạn dữ liệu và giả định đã dùng. Thanh khoản, chi phí, thị trường và lỗi vận hành có thể thay đổi.','No. Report 10% only for the specified data and assumptions. Liquidity, costs, markets and operational failures may differ.')],sources:[income,returns]},

{id:'algebra',moduleId:'math',title:c('Biến số và phương trình','Variables and equations'),summary:c('Dùng biến, hàm và phương trình để diễn tả quan hệ tài chính.','Use variables, functions and equations for financial relationships.'),why:c('Hiểu cấu trúc công thức giúp sửa mô hình thay vì chỉ thay số.','Understanding structure enables model changes rather than blind substitution.'),application:c('Giải giá hòa vốn và kiểm tra đơn vị trong hàm giá trị vị thế.','Solve break-even prices and check units in position valuation.'),prerequisites:['pnl'],project:'risk-lab',sections:[
sec('Biến và hàm','Variables and functions','Biến là tên đại diện một giá trị, cần ý nghĩa và đơn vị. Hàm là quy tắc cho đầu ra từ đầu vào. Với số lượng cố định $q=3$, hàm $V(P)=qP$ nhận giá mỗi đơn vị $P$ và trả giá trị cả vị thế $V$. Khi $P=20$, $V(P)=60$. Ngoặc trong tên hàm chỉ đầu vào, không phải phép nhân.\n\nKhi khảo sát tác động của giá, giữ lượng cố định. Nếu cả lượng và giá thay đổi, phải ghi nhận cả hai; không gán toàn bộ thay đổi giá trị cho thị trường.','A variable names a value with meaning and units. A function maps inputs to outputs. With fixed quantity $q=3$, $V(P)=qP$ maps unit price $P$ to position value $V$. At $P=20$, $V(P)=60$. Function parentheses specify an input rather than multiplication.\n\nHold quantity fixed when investigating price effects. When both change, account for both instead of attributing every value change to the market.'),
sec('Giải và kiểm tra','Solve and verify','Phương trình khẳng định hai biểu thức bằng nhau. Để giải, áp cùng phép toán hợp lệ lên hai vế. Mua hai đơn vị ở 50, tổng phí 4, không thu nhập khác: lãi theo giá bán $P$ là $L(P)=2(P-50)-4$. Hòa vốn đặt $L(P)=0$; cộng 4, chia 2 rồi cộng 50 được $P=52$.\n\nChỉ chia cho số khác không. Sau khi giải, thay kết quả ngược vào phương trình ban đầu. Ở đây bán thu 104, đúng bằng tiền mua 100 cộng phí 4.','An equation asserts equality. Solve it by applying the same valid operation to both sides. Buying two units at 50 with total fees of four gives profit $L(P)=2(P-50)-4$ at sale price $P$. Set $L(P)=0$, add four, divide by two and add fifty to obtain $P=52$.\n\nDivide only by nonzero values. Substitute the solution back: selling yields 104, matching purchase cash 100 plus fees four.'),
sec('Độ dốc và đơn vị','Slope and units','Trong hàm tuyến tính $y=ax+b$, $x$ là đầu vào, $y$ đầu ra, $a$ là thay đổi đầu ra khi đầu vào tăng một đơn vị, $b$ là giá trị khi đầu vào bằng không. Hàm lãi trên có độ dốc 2: giá bán tăng 1 USD làm lãi tăng 2 USD.\n\nĐơn vị là phép kiểm tra mạnh: giá mỗi cổ phiếu nhân số cổ phiếu thành tiền. Không cộng trực tiếp 5% với 4 USD; cần đổi tỷ lệ thành tiền theo một mốc vốn đã định nghĩa. Đồ thị giúp thấy quan hệ, nhưng không sửa được mô hình sai đơn vị.','For a linear function $y=ax+b$, $x$ is input, $y$ output, $a$ output change per input unit, and $b$ output at zero. The profit function above has slope two: a one USD sale-price increase adds two USD profit.\n\nUnits provide a strong check: price per share times shares yields money. Do not directly add 5% to four USD; convert the rate using a defined capital base. A graph reveals relationships but cannot repair inconsistent units.')],exercises:[
ex("algebra-1","concept","Trong V(P), ngoặc biểu thị điều gì, và cần giữ gì cố định để khảo sát riêng tác động của giá?","What do the parentheses in V(P) mean, and what must stay fixed to isolate price effects?","Phân biệt đầu vào của hàm với phép nhân.","Distinguish a function input from multiplication.","Ngoặc chỉ rằng giá P là đầu vào của hàm giá trị V, không có nghĩa V nhân P. Giữ số lượng tài sản cố định để thay đổi giá trị chỉ phản ánh thay đổi giá.","The parentheses identify price P as the input to value function V, not multiplication of V by P. Hold asset quantity fixed to isolate the effect of price changes."),
ex('algebra-2','calculation','Mua hai đơn vị ở 50, phí tổng 4. Giá bán mỗi đơn vị để hòa vốn?','Buy two units at 50 with total fees of four. What unit sale price breaks even?','Mỗi đơn vị gánh một nửa phí.','Each unit covers half the fee.','Giá 52. Hai đơn vị bán thu 104, bằng tổng chi ban đầu và phí.','Price 52 gives proceeds 104, matching purchase outlay plus fees.',52),
ex('algebra-3','concept','Vì sao trừ phí cả lệnh từ chênh lệch giá mỗi cổ phiếu có thể sai?','Why can subtracting a whole-order fee from a per-share price difference fail?','Kiểm tra quy mô của các khoản.','Check each amount’s scale.','Chúng không cùng quy mô. Nhân chênh lệch giá với lượng trước khi trừ tổng phí, hoặc đổi mọi khoản về mỗi cổ phiếu.','They use different scales. Multiply price difference by quantity before subtracting total fees, or convert everything to per-share terms.')],sources:[{title:'OpenStax — College Algebra 2e',url:'https://openstax.org/books/college-algebra-2e/pages/2-1-the-rectangular-coordinate-systems-and-graphs',section:'2.1 Equations, graphs and intercepts; ứng dụng lãi/lỗ tự biên soạn.'}]},

{id:'calculus',moduleId:'math',title:c('Đạo hàm','Derivatives'),summary:c('Hiểu độ nhạy cục bộ và tự dẫn xuất một đạo hàm từ tỷ số thay đổi.','Understand local sensitivity and derive a derivative from a difference quotient.'),why:c('Mô hình cần cho biết đầu ra nhạy ra sao với đầu vào.','Models need sensitivity to input changes.'),application:c('Kiểm tra độ nhạy giá trị vị thế bằng công thức và sai phân số.','Check position-value sensitivity analytically and numerically.'),prerequisites:['algebra'],project:'risk-lab',sections:[
sec('Tỷ số thay đổi','The difference quotient','Với hàm $f(x)$, đầu vào tăng từ $x$ đến $x+h$ làm đầu ra đổi $f(x+h)-f(x)$. $h$ là mức thay đổi đầu vào, khác không khi chia. Tỷ số $[f(x+h)-f(x)]/h$ đo thay đổi trung bình trên đoạn ấy.\n\nNếu tỷ số tiến tới cùng một giá trị hữu hạn khi $h$ tiến về 0 từ hai phía, giá trị đó là đạo hàm $f\\prime(x)$. Giới hạn nói về hành vi càng gần 0, không phải thay ngay 0 vào mẫu. Đạo hàm mô tả hàm, không dự báo giá thị trường.','For $f(x)$, moving input from $x$ to $x+h$ changes output by $f(x+h)-f(x)$. The input change $h$ is nonzero for division. The quotient $[f(x+h)-f(x)]/h$ measures average change across that interval.\n\nIf it approaches the same finite value as $h$ approaches zero from both sides, that value is derivative $f\\prime(x)$. A limit describes approaching zero, not substituting zero into a denominator. It describes a function, not future market direction.'),
sec('Dẫn xuất một ví dụ','Derive an example','Xét $f(x)=x^2$. Khai triển $(x+h)^2=x^2+2xh+h^2$, trừ $x^2$ rồi chia $h$ được $[(x+h)^2-x^2]/h=2x+h$. Khi bước tăng tiến về không, hạng cuối biến mất nên $f\\prime(x)=2x$.\n\nỞ $x=3$, độ nhạy bằng 6. Tăng đầu vào 0.01 cho ước tính tuyến tính tăng 0.06, trong khi tăng thực là 0.0601. Phần dư đến từ bình phương bước tăng. Xấp xỉ cục bộ không nhất thiết chính xác với thay đổi lớn.','Take $f(x)=x^2$. Expand $(x+h)^2=x^2+2xh+h^2$, subtract $x^2$ and divide by $h$ to get $[(x+h)^2-x^2]/h=2x+h$. As the increment approaches zero the final term vanishes, yielding $f\\prime(x)=2x$.\n\nAt $x=3$, sensitivity is six. An input increase of 0.01 predicts a linear increase of 0.06 while the actual increase is 0.0601. The remainder comes from the squared increment. Local approximations need not be accurate for large changes.'),
sec('Kiểm tra số','Numerical checking','Với $V(P)=qP$ và lượng $q$ cố định, tỷ số thay đổi bằng $q$ ở mọi bước giá khác không, nên $V\\prime(P)=q$. Năm cổ phiếu tăng giá trị 5 USD khi giá mỗi cổ phiếu tăng 1 USD; đây là quan hệ tuyến tính chính xác.\n\nVới hàm phức tạp, thử hai đầu vào gần nhau rồi chia chênh lệch. Bước quá lớn không còn cục bộ; bước quá nhỏ có thể gặp sai số làm tròn máy tính. So vài mức bước và trường hợp có đáp án biết trước. Hàm có góc gãy có thể không có đạo hàm tại điểm gãy.','For $V(P)=qP$ with fixed $q$, every nonzero-step difference quotient equals $q$, hence $V\\prime(P)=q$. Five shares gain five USD of value per one USD price increase: an exact linear relation.\n\nFor complex functions compare nearby inputs and divide differences. Large steps may not be local; very small steps can amplify floating-point rounding. Compare step sizes and known-answer cases. A kinked function may not be differentiable at its kink.')],exercises:[
ex("calculus-1","concept","Vì sao không thay h bằng 0 ngay trong tỷ số thay đổi?","Why not substitute zero for h immediately in the difference quotient?","Xem mẫu số trước khi lấy giới hạn.","Inspect the denominator before taking a limit.","Tỷ số có h ở mẫu nên không xác định tại h bằng 0. Ta xét những bước khác không ngày càng nhỏ rồi xem tỷ số có tiến tới một giá trị chung hay không.","The denominator contains h, so the quotient is undefined at zero. Consider successively smaller nonzero steps and ask whether the quotient approaches a common value."),
ex("calculus-2","calculation","Với hàm bình phương vừa xét, đạo hàm tại x = 4 bằng bao nhiêu?","For the squared function just derived, what is its derivative at x = 4?","Sau khi lấy giới hạn, đạo hàm bằng hai lần đầu vào.","After taking the limit, the derivative is twice the input.","Tỷ số thay đổi rút gọn thành $2x+h$; khi h tiến về 0 còn $2x$. Tại đầu vào 4, đạo hàm bằng 8. Đây là độ nhạy cục bộ, không phải giá trị hàm bằng 16.","The difference quotient simplifies to $2x+h$; as h approaches zero it leaves $2x$. At input four the derivative is eight. This is local sensitivity, not the function value of sixteen.",8),
ex('calculus-3','concept','Độ nhạy theo giá dương có chứng minh giá sắp tăng không?','Does positive price sensitivity prove price will rise?','Phân biệt quan hệ mô hình và dự báo đầu vào.','Separate model response from forecasting inputs.','Không. Nó chỉ nói đầu ra tăng cục bộ nếu giá tăng nhỏ khi giữ các đầu vào khác. Hướng giá tương lai là câu hỏi dự báo khác.','No. It says output locally rises if price rises slightly with other inputs fixed. Future price direction is a separate forecast.')],sources:[{title:'OpenStax — Calculus Volume 1',url:'https://openstax.org/books/calculus-volume-1/pages/3-1-defining-the-derivative',section:'3.1 Defining the Derivative: difference quotient, limits and local slope.'}]},
{id:'probability',moduleId:'math',title:c('Xác suất','Probability'),summary:c('Mô tả kết quả chưa biết và phân biệt xác suất, kỳ vọng, độ phân tán.','Describe uncertain outcomes and distinguish probability, expectation and dispersion.'),why:c('Nghiên cứu giao dịch đánh giá cả tập kết quả có thể xảy ra.','Trading research evaluates a range of possible outcomes.'),application:c('So sánh chiến lược thường thắng nhỏ nhưng đôi lúc lỗ lớn với chiến lược có tỷ lệ thắng thấp hơn.','Compare frequent small wins with occasional large losses against a strategy with a lower win rate.'),prerequisites:['algebra','risk'],project:'risk-lab',sections:[
sec('Kết quả và xác suất','Outcomes and probabilities','Một kết quả là điều có thể xảy ra, chẳng hạn lãi 10 USD hoặc lỗ 5 USD. Biến ngẫu nhiên $X$ gán một số cho mỗi kết quả; ở đây là lãi/lỗ tính bằng USD. Xác suất mô tả mức độ có thể xảy ra của kết quả theo mô hình. Mỗi xác suất nằm từ 0 đến 1; xác suất của toàn bộ các kết quả loại trừ nhau và bao phủ mọi khả năng phải cộng thành 1.\n\nVí dụ giả định xác suất lãi 10 là 0.6, lỗ 5 là 0.4. Hai số này là đầu vào mô hình, chưa phải sự thật đã được chứng minh. Đếm số lần thắng trong dữ liệu là cách ước lượng, còn đánh giá độ tin cậy của ước lượng là việc tiếp theo.','An outcome is something that can happen, such as gaining ten USD or losing five USD. Random variable $X$ assigns a number to each outcome, here profit or loss in USD. A probability expresses how likely an outcome is under a model. Each probability lies between zero and one; probabilities for mutually exclusive outcomes covering all possibilities sum to one.\n\nSuppose the probability of gaining ten is 0.6 and of losing five is 0.4. These are model inputs, not established facts. Counting historical wins estimates a probability; assessing the reliability of that estimate is a further task.'),
sec('Kỳ vọng','Expected value','Kỳ vọng $E[X]$ là trung bình có trọng số: nhân từng giá trị với xác suất của nó rồi cộng. Trong ví dụ, $E[X]=0.6(10)+0.4(-5)=4$. Dấu âm biểu thị lỗ. Kỳ vọng có cùng đơn vị USD với lãi/lỗ, không phải một xác suất.\n\nKhông kết quả riêng lẻ nào trong ví dụ bằng 4. Kỳ vọng mô tả tâm của phân phối, không hứa mỗi giao dịch kiếm được 4 USD. Nếu mô hình xác suất đúng và những điều kiện thích hợp cho luật số lớn được đáp ứng, trung bình của nhiều lần thử có xu hướng gần kỳ vọng. Chuỗi giao dịch thực có thể phụ thuộc nhau hoặc thay đổi theo thời gian; không được mặc nhiên áp dụng kết luận đó.','Expectation $E[X]$ is a weighted average: multiply each value by its probability and add. Here $E[X]=0.6(10)+0.4(-5)=4$. A negative value represents a loss. Expectation has the same USD unit as profit or loss, not probability units.\n\nNo individual outcome here equals four. Expectation describes the centre of the distribution, not a promise of four USD per trade. If the probability model is correct and suitable conditions for a law of large numbers hold, an average over many trials tends toward expectation. Real trades may be dependent or change over time; this conclusion cannot simply be assumed.'),
sec('Độ phân tán và chi phí','Dispersion and costs','Đặt $m=E[X]$. Phương sai $E[(X-m)^2]$ lấy trung bình có trọng số của độ lệch bình phương. Bình phương tránh việc lệch dương và âm triệt tiêu nhau. Căn bậc hai của phương sai là độ lệch chuẩn, trở lại cùng đơn vị với biến ban đầu. Hai chiến lược có cùng kỳ vọng có thể có độ phân tán và mức lỗ cực đoan rất khác nhau.\n\nNếu mỗi lần thử đều trả khoản phí cố định $c$, kết quả sau phí là $X-c$ và $E[X-c]=E[X]-c$. Phí 5 USD làm kỳ vọng 4 USD thành âm 1 USD. Tỷ lệ thắng cao hoặc kỳ vọng trước phí dương chưa đủ để đánh giá một chiến lược.','Let $m=E[X]$. Variance $E[(X-m)^2]$ averages squared deviations using probability weights. Squaring prevents positive and negative deviations cancelling. Its square root is standard deviation, restoring the original unit. Strategies with equal expectations can have very different dispersion and extreme losses.\n\nIf every trial pays fixed cost $c$, its net outcome is $X-c$ and $E[X-c]=E[X]-c$. A cost of five USD turns an expectation of four into negative one. A high win rate or positive pre-cost expectation alone cannot establish strategy quality.')],exercises:[
ex("probability-1","concept","Một mô hình chỉ có hai kết quả loại trừ nhau: lãi hoặc lỗ. Có hợp lệ không nếu gán xác suất 0.6 cho mỗi kết quả?","A model has only two mutually exclusive outcomes: gain or loss. Is assigning probability 0.6 to each valid?","Hai kết quả đã bao phủ mọi khả năng của mô hình.","The two outcomes exhaust the model’s possibilities.","Không. Tổng là 1.2, vượt 1. Khi các kết quả loại trừ nhau và bao phủ toàn bộ khả năng, xác suất phải cộng đúng thành 1. Cần sửa mô hình trước khi tính tiếp.","No. Their sum is 1.2, exceeding one. Probabilities of mutually exclusive, exhaustive outcomes must sum to one. Correct the model before further calculations."),
ex('probability-2','calculation','Thắng 90% số lần, mỗi lần lãi 1; thua 10%, mỗi lần lỗ 20. Kỳ vọng trước phí?','Win 90% of trials for a gain of one, lose 10% for a loss of twenty. What is pre-cost expectation?','Tỷ lệ thắng không phản ánh độ lớn khoản lỗ.','Win rate ignores loss size.','Kết quả $0.9(1)+0.1(-20)=-1.1$. Tỷ lệ thắng cao vẫn có thể đi cùng kỳ vọng âm.','The result is $0.9(1)+0.1(-20)=-1.1$. A high win rate can accompany negative expectation.',-1.1),
ex('probability-3','derivation','Vì sao phí cố định c làm kỳ vọng giảm đúng c?','Why does a fixed cost c reduce expectation by exactly c?','Phân phối phép nhân qua từng kết quả, rồi dùng tổng xác suất bằng 1.','Distribute multiplication over each outcome and use probabilities summing to one.','Mỗi kết quả bị trừ c. Khi lấy trung bình có trọng số, tổng phần trừ bằng c nhân tổng xác suất, tức c. Vì vậy $E[X-c]=E[X]-c$. Kết luận này không thay thế việc mô hình hóa phí thay đổi theo kết quả.','Each outcome loses c. In the weighted average, total subtraction is c times the sum of probabilities, hence c. Thus $E[X-c]=E[X]-c$. This does not replace modelling costs that vary by outcome.')],sources:[{title:'OpenStax — Introductory Statistics 2e',url:'https://openstax.org/books/introductory-statistics-2e/pages/4-2-mean-or-expected-value-and-standard-deviation',section:'4.2 Mean or Expected Value and Standard Deviation; ví dụ giao dịch tự biên soạn.'}]},

{id:'estimation',moduleId:'math',title:c('Ước lượng','Estimation'),summary:c('Phân biệt trung bình mẫu với đại lượng cần tìm và lượng hóa sai số trong một mô hình đơn giản.','Separate a sample average from its target and quantify uncertainty in a simple model.'),why:c('Một kết quả đẹp trên dữ liệu quá khứ vẫn có thể do may mắn hoặc lựa chọn mẫu.','An attractive historical result may reflect luck or sample selection.'),application:c('Báo cáo lợi suất trung bình kèm giả định và độ bất định trước khi so sánh chiến lược.','Report average return with assumptions and uncertainty before comparing strategies.'),prerequisites:['probability','returns'],project:'risk-lab',sections:[
sec('Mẫu và tham số','Samples and parameters','Tham số là đặc trưng của phân phối mà ta muốn biết, chẳng hạn kỳ vọng lợi suất $m$. Mẫu là những quan sát thực có được. Với $n$ quan sát $x_1,...,x_n$, trung bình mẫu là $a=(x_1+...+x_n)/n$. Khác với tham số, giá trị của trung bình mẫu thay đổi khi thu mẫu khác.\n\nBa lợi suất 0.01, 0.02 và 0.03 có trung bình 0.02. Điều này mô tả dữ liệu đã quan sát, chưa chứng minh kỳ vọng tương lai là 2%. Chọn một giai đoạn tăng mạnh hoặc chỉ giữ những cổ phiếu còn niêm yết đều có thể khiến mẫu không đại diện cho câu hỏi nghiên cứu.','A parameter describes the distribution we want to learn about, such as expected return $m$. A sample contains the observations actually available. For $n$ observations $x_1,...,x_n$, sample mean is $a=(x_1+...+x_n)/n$. Unlike the target parameter, its value changes across samples.\n\nReturns of 0.01, 0.02 and 0.03 average to 0.02. This describes observations, not proof that future expected return is 2%. Selecting a strong market period or retaining only still-listed stocks can make a sample unrepresentative of the research question.'),
sec('Sai số chuẩn','Standard error','Để có một phép tính rõ ràng, giả định các quan sát độc lập, cùng phân phối, có phương sai hữu hạn $s^2$. Ở đây $s$ là độ lệch chuẩn của phân phối, chưa phải độ lệch chuẩn tính từ mẫu. Tính độc lập khiến phương sai của tổng bằng tổng phương sai: $Var(x_1+...+x_n)=ns^2$. Chia tổng cho $n$ chia phương sai cho $n^2$, nên $Var(a)=s^2/n$.\n\nSai số chuẩn của trung bình là độ lệch chuẩn của trung bình qua nhiều mẫu: $SE=s/\\sqrt{n}$. Cỡ mẫu gấp bốn chỉ làm sai số chuẩn giảm một nửa theo các giả định trên. Nhân bản dòng dữ liệu không tạo thêm quan sát độc lập. Lợi suất có tương quan theo thời gian cần cách đánh giá sai số phù hợp.','For a transparent calculation, assume independent, identically distributed observations with finite variance $s^2$. Here $s$ is the distribution’s standard deviation, not a standard deviation estimated from this sample. Independence makes variance of the sum additive: $Var(x_1+...+x_n)=ns^2$. Dividing the sum by $n$ divides variance by $n^2$, so $Var(a)=s^2/n$.\n\nThe standard error measures variation of the sample mean across samples: $SE=s/\\sqrt{n}$. Quadrupling sample size only halves standard error under these assumptions. Duplicating rows does not create independent observations. Serially correlated returns need an appropriate uncertainty calculation.'),
sec('Diễn giải khoảng ước lượng','Interpreting an interval','Nếu biết độ lệch chuẩn của phân phối và trung bình mẫu có phân phối chuẩn hoặc xấp xỉ chuẩn phù hợp, một khoảng tin cậy 95% cho kỳ vọng là $[a-1.96SE,a+1.96SE]$. Hệ số 1.96 đến từ vùng giữa chứa khoảng 95% xác suất của phân phối chuẩn chuẩn hóa.\n\nÝ nghĩa tần suất: lặp lại quy trình lấy mẫu và dựng khoảng nhiều lần, khoảng 95% những khoảng ấy chứa tham số cố định. Không có nghĩa 95% lợi suất ngày mai nằm trong khoảng này. Khi chưa biết độ lệch chuẩn, phải ước lượng và dùng phương pháp phù hợp; không tự xem một con số ước lượng là đã biết chính xác. Khoảng hẹp cũng không sửa được dữ liệu sai, thiên lệch lựa chọn hoặc việc thử rất nhiều chiến lược rồi chỉ báo cáo chiến lược thắng.','If population standard deviation is known and the sample mean is normally distributed or suitably approximated by a normal distribution, a 95% confidence interval for the mean is $[a-1.96SE,a+1.96SE]$. The factor 1.96 comes from the central region containing approximately 95% of standard normal probability.\n\nThe frequentist interpretation repeats sampling and interval construction: about 95% of those intervals cover the fixed parameter. It does not put 95% of tomorrow’s returns in this interval. Unknown population standard deviation requires estimation and an appropriate method; an estimate is not an exactly known input. A narrow interval does not fix bad data, selection bias or reporting only the winner after trying many strategies.')],exercises:[
ex("estimation-1","concept","Trung bình mẫu 2% có chứng minh kỳ vọng lợi suất tương lai đúng bằng 2% không?","Does a sample average of 2% prove future expected return is exactly 2%?","Phân biệt số tính từ dữ liệu với đặc trưng phân phối cần ước lượng.","Separate a statistic from the distribution property it estimates.","Không. Trung bình mẫu mô tả các quan sát đã có và thay đổi khi lấy mẫu khác. Kỳ vọng là đại lượng cần ước lượng; tính đại diện và bất định của mẫu vẫn phải được đánh giá.","No. The sample mean describes available observations and changes across samples. Expectation is the target being estimated; sample representativeness and uncertainty still require assessment."),
ex('estimation-2','calculation','Theo mô hình độc lập cùng phân phối, độ lệch chuẩn đã biết là 0.1 và có 100 quan sát. Sai số chuẩn trung bình?','Under the independent, identically distributed model, known standard deviation is 0.1 and there are 100 observations. What is the mean’s standard error?','Chia độ lệch chuẩn cho căn bậc hai của cỡ mẫu.','Divide standard deviation by the square root of sample size.','Căn của 100 bằng 10 nên sai số chuẩn là 0.01. Nó đo bất định của trung bình, không phải độ lệch chuẩn của một lợi suất riêng lẻ.','The square root of 100 is ten, giving standard error 0.01. It measures uncertainty of the mean, not the standard deviation of an individual return.',0.01),
ex("estimation-3","concept","Một báo cáo gọi khoảng tin cậy 95% của trung bình là khoảng chứa 95% lợi suất ngày mai. Hãy sửa cách diễn giải.","A report calls a 95% confidence interval for the mean a range containing 95% of tomorrow’s returns. Correct that interpretation.","Đối tượng được ước lượng là trung bình, không phải một quan sát mới.","The target is the mean, not a new observation.","Khoảng này ước lượng kỳ vọng. Theo mô hình, nếu lặp việc lấy mẫu và dựng khoảng, khoảng 95% các khoảng tạo ra sẽ chứa kỳ vọng cố định. Muốn dự báo lợi suất ngày mai cần mô hình và khoảng dự báo cho một quan sát mới.","The interval estimates the expected value. Under the model, repeating sampling and interval construction yields intervals that cover the fixed expectation about 95% of the time. Predicting tomorrow requires a predictive model and an interval for a new observation.")],sources:[{title:'OpenStax — Introductory Statistics 2e',url:'https://openstax.org/books/introductory-statistics-2e/pages/8-1-a-single-population-mean-using-the-normal-distribution',section:'8.1 A Single Population Mean Using the Normal Distribution; known population standard deviation and confidence intervals.'}]},

{id:'python',moduleId:'python',title:c('Hàm và kiểm thử','Functions and tests'),summary:c('Viết một hàm tính lợi suất có kiểm tra đầu vào và những ca kiểm thử hiểu được.','Write a return function with input validation and understandable tests.'),why:c('Tính đúng một ví dụ chưa đủ; mã phải xử lý được các trường hợp thuộc phạm vi của nó.','One correct example is insufficient; code must handle cases within its stated scope.'),application:c('Tạo phép tính dùng chung cho báo cáo sổ giao dịch, rồi kiểm tra trước khi nối dữ liệu thật.','Build a shared calculation for trade-ledger reports and test it before connecting real data.'),prerequisites:['returns'],project:'data-pipeline',sections:[
sec('Đầu vào và kết quả','Inputs and outputs','Biến là tên gắn với một giá trị. Trong Python, 100 là số, còn "100" là chuỗi ký tự; dữ liệu đọc từ tệp có thể cần chuyển kiểu trước khi tính. Hàm gom một phép xử lý có tên, nhận đối số làm đầu vào và trả kết quả.\n\nHàm ở đây nhận initial là vốn đầu kỳ dương và final là giá trị cuối kỳ trên cùng đơn vị tiền. Phí phải được phản ánh trong hai đầu vào theo cùng quy ước. Phạm vi là một kỳ không có nạp/rút tiền giữa kỳ. Kết quả là lợi suất dạng thập phân, không phải phần trăm đã nhân 100.','A variable names a value. In Python, 100 is a number while "100" is a string; file inputs may require conversion before arithmetic. A function names a calculation, takes arguments as inputs and returns an output.\n\nOur function takes initial as positive initial capital and final as end-period value in the same currency. Both must already reflect fees under a consistent convention. Its scope is one period with no intermediate deposits or withdrawals. The result is a decimal return, not a percentage multiplied by 100.'),
sec('Viết hàm','Write the function','Đoạn mã sau dùng thư viện chuẩn math để kiểm tra số hữu hạn. if chỉ chạy nhánh khi điều kiện đúng; raise báo lỗi cho bên gọi; return trả kết quả và kết thúc hàm. def bắt đầu định nghĩa hàm; phần thụt lề là thân hàm.\n\n```python\nimport math\n\ndef simple_return(initial, final):\n    if not math.isfinite(initial) or not math.isfinite(final):\n        raise ValueError("Cash values must be finite")\n    if initial <= 0:\n        raise ValueError("Initial capital must be positive")\n    return (final - initial) / initial\n```\n\nHàm giả định đầu vào đã là số. Giá trị NaN biểu thị giá trị số không xác định, còn vô cực không phải số tiền hợp lệ ở đây. Vốn đầu kỳ bằng không làm phép chia vô nghĩa; vốn âm nằm ngoài mô hình đã chọn. Thông báo lỗi tốt hơn việc âm thầm trả một con số gây hiểu nhầm.','This code uses the standard math library to check finite numbers. if runs a branch when its condition is true; raise signals an error to the caller; return supplies the result and exits the function. def begins a function definition; indentation marks its body.\n\n```python\nimport math\n\ndef simple_return(initial, final):\n    if not math.isfinite(initial) or not math.isfinite(final):\n        raise ValueError("Cash values must be finite")\n    if initial <= 0:\n        raise ValueError("Initial capital must be positive")\n    return (final - initial) / initial\n```\n\nInputs are assumed already numeric. NaN represents an undefined numerical value; infinity is not a valid cash amount here. Zero initial capital makes division undefined, while negative capital is outside the chosen model. An explicit error is preferable to silently returning a misleading number.'),
sec('Kiểm thử theo ý nghĩa','Test the meaning','Kiểm thử đối chiếu hành vi với điều ta biết trước. Vốn 100 thành 110 phải cho khoảng 0.1; thành 90 cho khoảng âm 0.1; không đổi cho 0. Số thực trên máy tính thường chỉ là xấp xỉ, nên dùng math.isclose để so gần bằng thay vì đòi mọi số thập phân bằng tuyệt đối.\n\n```python\nassert math.isclose(simple_return(100, 110), 0.1)\nassert math.isclose(simple_return(100, 90), -0.1)\nassert simple_return(100, 100) == 0\n```\n\nassert ở đây phục vụ kiểm thử; kiểm tra đầu vào thực tế vẫn dùng if và raise vì assert có thể bị tắt khi chạy Python với tối ưu hóa. Kiểm thử công thức không phát hiện việc người gọi nhập giá BTC bằng USD nhưng vốn bằng VND. Điều kiện tài chính phải được kiểm tra ở lớp chuẩn bị dữ liệu.','Tests compare behaviour with known expectations. Capital of 100 ending at 110 should yield about 0.1; ending at 90 about negative 0.1; unchanged capital gives zero. Machine floating-point values often approximate decimal numbers, so math.isclose checks numerical closeness instead of requiring exact equality everywhere.\n\n```python\nassert math.isclose(simple_return(100, 110), 0.1)\nassert math.isclose(simple_return(100, 90), -0.1)\nassert simple_return(100, 100) == 0\n```\n\nHere assert serves testing; runtime validation still uses if and raise because Python optimization can disable assertions. Formula tests cannot detect a caller combining a BTC value in USD with initial capital in VND. Financial input conditions belong in data preparation.')],exercises:[
ex("python-1","concept","Hàm nhận vốn đầu bằng USD và giá trị cuối bằng VND. Đầu vào có phù hợp dù cả hai đều là số không?","The function receives initial capital in USD and ending value in VND. Are those valid inputs even if both are numbers?","Điều kiện về dữ liệu không chỉ là kiểu số.","Input conditions involve more than numeric type.","Không. Hai số phải cùng đơn vị tiền và cùng quy ước phí, không có dòng vốn ngoài giữa kỳ. Cần chuẩn hóa và xác nhận ý nghĩa trước khi gọi hàm.","No. Both amounts must share a currency and fee convention, with no intermediate external flows. Normalize and verify their meaning before calling the function."),
ex('python-2','calculation','simple_return(200, 220) trả về bao nhiêu?','What does simple_return(200, 220) return?','Hàm trả dạng thập phân.','The function returns a decimal.','Chênh lệch 20 chia 200 bằng 0.1, tương đương 10%. Hàm không trả 10.','The difference twenty divided by 200 is 0.1, equivalent to 10%. The function does not return ten.',0.1),
ex("python-3","implementation","Viết một kiểm thử cho vốn 200 giảm còn 180, dùng cách so gần bằng vừa học.","Write a test for capital falling from 200 to 180 using the approximate comparison just introduced.","Lợi suất kỳ vọng là âm 0.1, không phải âm 10.","Expected return is negative 0.1, not negative ten.","```python\nassert math.isclose(simple_return(200, 180), -0.1)\n```\nKiểm thử phát hiện lỗi dấu hoặc nhầm tỷ lệ với phần trăm. Nó không chứng minh các khoản tiền đầu vào đã bao gồm đúng phí và dòng tiền.","```python\nassert math.isclose(simple_return(200, 180), -0.1)\n```\nThis detects sign errors or confusion between decimal and percentage returns. It does not establish that the inputs correctly include fees and cash flows.")],sources:[{title:'Python Tutorial — More Control Flow Tools',url:'https://docs.python.org/3/tutorial/controlflow.html',section:'4.1 if Statements; 4.8 Defining Functions.'},{title:'Python Standard Library — math',url:'https://docs.python.org/3/library/math.html',section:'math.isfinite; math.isclose. Code examples original.'}]},

{id:'data',moduleId:'python',title:c('Dữ liệu thị trường','Market data'),summary:c('Tạo bản ghi có nguồn gốc, thời điểm và quy tắc xử lý thiếu dữ liệu rõ ràng.','Create records with clear provenance, timing and missing-data rules.'),why:c('Một mô hình tính đúng trên dữ liệu sai vẫn dẫn đến kết luận sai.','A correct calculation on incorrect data still produces a wrong conclusion.'),application:c('Xây đầu vào cho nghiên cứu cổ phiếu, crypto và FX mà không dùng thông tin tương lai.','Build equity, crypto and FX research inputs without using future information.'),prerequisites:['python','cash-flow'],project:'data-pipeline',sections:[
sec('Một giá cần những gì?','What identifies a price?','Một con số giá cần đi cùng tài sản, nơi giao dịch, loại giá, đơn vị và thời điểm. Giá đóng cửa, giá giao dịch cuối, giá chào mua và giá chào bán phục vụ những câu hỏi khác nhau. Với crypto còn phải phân biệt thị trường giao ngay với hợp đồng phái sinh; với FX phải ghi chiều của cặp tiền.\n\nPhân biệt thời điểm sự kiện với thời điểm dữ liệu được công bố và thời điểm hệ thống nhận được. Báo cáo cho quý kết thúc tháng Ba nhưng công bố tháng Tư chưa tồn tại để dùng vào cuối tháng Ba. Khi mô phỏng quyết định quá khứ, chỉ dùng thông tin đã sẵn có tại thời điểm quyết định. Dùng dữ liệu công bố sau là sai lệch nhìn trước.','A price needs an asset, venue, price type, unit and timestamp. Closing prices, last trades, bids and asks answer different questions. Crypto also requires distinguishing spot from derivatives; FX requires an explicit currency-pair direction.\n\nSeparate event time, publication time and system receipt time. A report covering a quarter ending in March but published in April was not available at the end of March. A historical decision simulation must use information available at decision time. Using later publications introduces look-ahead bias.'),
sec('Thiếu và trùng dữ liệu','Missing and duplicate data','Thiếu dữ liệu nghĩa là chưa có giá trị biết được, không mặc nhiên là giá trị bằng không. pandas có isna để nhận diện giá trị thiếu; biểu diễn cụ thể còn tùy kiểu dữ liệu. Điền giá bằng 0 có thể tạo khoản lỗ giả 100%, rồi làm lợi suất kỳ sau chia cho không.\n\nMang giá gần nhất tiến về sau là một giả định rằng giá cũ còn phù hợp cho mục đích đang xét; nó không chứng minh có thể giao dịch tại giá ấy. Cần lưu cờ đã điền và giới hạn tuổi dữ liệu. Với bản ghi trùng, dùng mã sự kiện và quy tắc nguồn: hai giao dịch có cùng giá và thời gian làm tròn vẫn có thể là hai giao dịch thật. Không xóa chỉ vì nhìn giống nhau.','Missing data means no known value, not automatically zero. pandas provides isna to identify missing values; their representation depends on data type. Filling a price with zero can fabricate a 100% loss and then create division by zero in the next return.\n\nCarrying the last price forward assumes that an old observation remains suitable for the current purpose; it does not prove execution was possible at that price. Preserve a fill flag and limit data age. For duplicates, use event identifiers and source rules: two trades with equal prices and rounded times may still be distinct trades. Do not delete records merely because they look alike.'),
sec('Nguồn gốc và phiên bản','Provenance and versions','Giữ bản dữ liệu gốc cùng URL nguồn, thời điểm lấy, phiên bản hoặc ngày phát hành và quyền sử dụng. Ghi riêng các bước chuẩn hóa: đổi múi giờ, xử lý thiếu, đổi đơn vị và điều chỉnh giá. Mã băm giúp nhận biết nội dung có đổi hay không, không chứng minh nội dung đúng. Từ một kết quả nghiên cứu phải lần ngược được dữ liệu và phép biến đổi đã dùng.\n\nDữ liệu kinh tế có thể được sửa sau công bố. ALFRED lưu các phiên bản theo thời điểm để nghiên cứu điều từng được biết, nhưng vẫn phải kiểm tra ngày sẵn có và độ trễ nguồn. Với cổ phiếu, giá đã điều chỉnh có thể phản ánh cổ tức; cộng cổ tức thêm lần nữa có thể đếm trùng. Với dữ liệu SEC, ngày kết thúc kỳ báo cáo không thay thế ngày nộp hồ sơ. Tải được dữ liệu không đồng nghĩa được quyền tái phân phối toàn bộ.','Retain raw data with its source URL, retrieval time, version or release date and usage rights. Record normalization separately: timezone conversion, missing-value handling, units and price adjustments. A hash detects content changes; it does not establish correctness. Every research result should be traceable to its inputs and transformations.\n\nEconomic series can be revised after publication. ALFRED stores vintages for studying what was known, but availability dates and source delays still matter. An adjusted equity price may already reflect dividends; adding dividends again can double-count them. For SEC data, a reporting-period end does not replace filing time. Download access does not automatically grant permission to redistribute everything.')],exercises:[
ex("data-1","concept","Một tệp chỉ ghi BTC và giá 50000. Vì sao chưa thể dùng ngay làm giá mua trong mô phỏng?","A file records only BTC and a price of 50000. Why is it insufficient as a simulated purchase price?","Kiểm tra sản phẩm, đồng tiền, loại giá và thời điểm.","Check product, currency, price type and timing.","Chưa biết sàn, giao ngay hay phái sinh, đồng tiền báo giá, giá ask hay giá giao dịch cuối, thời điểm và lúc thông tin sẵn có. Cần các trường đó để xác định bản ghi có phù hợp quyết định mua đang mô phỏng hay không.","Venue, spot versus derivative, quote currency, ask versus last-trade price, timestamp and availability are unknown. These fields are needed to determine whether the record fits the simulated purchase decision."),
ex('data-2','calculation','Một nguồn xác nhận mã sự kiện là duy nhất. Ba bản ghi có mã A, B, A; hai bản A giống nhau. Sau khử bản sao còn bao nhiêu sự kiện?','A source guarantees unique event identifiers. Records have IDs A, B, A; the A records are identical. How many events remain after deduplication?','Đếm mã duy nhất theo hợp đồng nguồn.','Count unique IDs under the source contract.','Còn 2 sự kiện. Giữ một bản A và một bản B, đồng thời ghi nhận đã bỏ bản lặp. Nếu mã không duy nhất toàn nguồn, cần thêm khóa như nơi giao dịch hoặc ngày.','Two events remain: one A and one B, with deduplication recorded. If IDs are not globally unique, include keys such as venue or date.',2),
ex('data-3','implementation','Báo cáo có kỳ kết thúc 31/3, công bố 15/4. Bộ lọc dữ liệu cho quyết định ngày 1/4 nên dùng mốc nào?','A report covers a period ending March 31 and is released April 15. Which date should filter information for an April 1 decision?','Lọc theo lúc thông tin sẵn có, không chỉ kỳ báo cáo.','Filter by availability, not merely reporting period.','Dùng thời điểm công bố hoặc thời điểm nhận đáng tin cậy, có xét múi giờ và độ trễ. Báo cáo này phải bị loại khỏi thông tin ngày 1/4 vì chưa công bố. Lưu cả ngày kỳ báo cáo và thời điểm sẵn có trong hai trường riêng.','Use publication or reliable receipt time, accounting for timezone and latency. Exclude this report from April 1 information because it was not published yet. Store reporting-period date and availability time separately.')],sources:[{title:'pandas — Working with missing data',url:'https://pandas.pydata.org/docs/user_guide/missing_data.html',section:'Values considered missing; detecting missing values; filling missing data.'},{title:'Federal Reserve Bank of St. Louis — ALFRED Help',url:'https://alfred.stlouisfed.org/help',section:'Vintage dates and real-time periods; archived economic data.'},{title:'SEC — EDGAR APIs',url:'https://www.sec.gov/search-filings/edgar-application-programming-interfaces',section:'Submissions API and XBRL data APIs; reporting and filing metadata.'}]},
];
